import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"Chip","description":"","frontmatter":{},"headers":[],"relativePath":"components/chip.md","filePath":"components/chip.md"}'),i={name:"components/chip.md"};function h(d,e,s,n,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="chip" tabindex="-1">Chip <a class="header-anchor" href="#chip" aria-label="Permalink to &quot;Chip&quot;">​</a></h1><p>Chip is a chosen value that can be removed, such as a filter.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for chosen values, one Chip each in a <a href="./row">Row</a>; the ✕ removes one. With <code>onclick</code> the text can be pressed too, for example to edit the value. A Chip without a remove button is a value that can be pressed. A state or a kind is not a Chip: use <a href="./badge">Badge</a> or <a href="./tag">Tag</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>onremove</code></td><td></td><td>Removes the value; without it no ✕ shows</td></tr><tr><td><code>onclick</code></td><td></td><td>Makes the text pressable</td></tr><tr><td><code>removeLabel</code></td><td></td><td>The name of the ✕ (default: the <code>removeValue</code> message)</td></tr><tr><td><code>children</code></td><td>required</td><td>The value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A chip is a rectangle, since it can be pressed, with the height of a small button (<code>--kata-height-button-sm</code>), a strong line and the raise surface. pad-sm at both sides, and pad-2xs at the right when it has a ✕, which carries its own white space: a square of <code>--kata-height-badge</code>, whose hit area and hover surface are that square. The text is trimmed to its ink; a long value ends with an ellipsis. Pressable text underlines on hover.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/chip/" title="Chip" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/chip/" target="_blank" rel="noopener">Chip</a></figcaption></figure>',10)])])}const m=t(i,[["render",h]]);export{u as __pageData,m as default};
